"""Offline dashboard sourced exclusively from deterministic v1.0 result CSVs."""
from pathlib import Path
import csv, json, html
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'results/v10'
def rd(name):
    with (OUT/name).open(newline='',encoding='utf-8') as f:return list(csv.DictReader(f))
data={
  'target':rd('cbo_fy_target_gaps.csv'),
  'options':rd('2024_cbo_option_analogues_FY2034_NOT_ADDITIVE.csv'),
  'hi':rd('cms_2026_hi_frozen_three_scenarios_NOT_OACT_SCORE.csv'),
  'thresholds':rd('cms_hi_reserve_thresholds_NOT_SCORE.csv'),
  'vat':rd('vat_fixed_all_pce_capacity_bound_NOT_LEGAL_TAX_BASE.csv'),
  'household':rd('vat_household_break_even_SYMBOLIC_NOT_NATIONAL.csv'),
  'surtax':rd('cbo2028_top1_drafted_Magi_surtax_liability_lower_bound_NOT_SCORE.csv'),
  'defense':rd('defense_budget_authority_deltas_NOT_FY_OUTLAYS.csv'),
}
serialized=json.dumps(data,ensure_ascii=True,separators=(',',':')).replace('<','\\u003c')
htmlsource='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>FiscalRazor — Actual Policy Potential, v1.0</title>
<style>
:root{color-scheme:dark;--bg:#090f1b;--surface:#111d2f;--hi:#19acba;--ink:#e7efff;--muted:#a2b4cb;--warn:#e8bd69;--edge:#2c4058}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#112846,var(--bg) 45%);color:var(--ink);font-family:system-ui,-apple-system,'Segoe UI',sans-serif;line-height:1.5}main{max-width:1160px;margin:auto;padding:28px 18px 50px}h1{font-size:clamp(1.8rem,4vw,3rem);letter-spacing:-.04em;margin:0 0 12px}h2{font-size:1.35rem;margin:0 0 16px}p{margin:.5rem 0 1rem;color:var(--muted)}header{padding:16px 0 30px}.tag{font-size:.8rem;letter-spacing:.15em;text-transform:uppercase;color:#59ccd8;font-weight:800}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{background:rgba(17,29,47,.96);border:1px solid var(--edge);border-radius:16px;padding:22px;margin-bottom:16px}.wide{grid-column:span 2}.numbers{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.metric{border:1px solid var(--edge);border-radius:12px;padding:12px}.metric strong{display:block;color:#c9f7fc;font-size:clamp(1.3rem,2.5vw,2rem);font-variant-numeric:tabular-nums}.metric small{display:block;color:var(--muted);font-size:.8rem}.warn{border-left:4px solid var(--warn);padding:12px 14px;background:#28261955;margin:15px 0;border-radius:4px;color:#f0debc;font-size:.95rem}.choice{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}button{border:1px solid var(--edge);border-radius:9px;background:#14253a;color:var(--ink);padding:8px 12px;cursor:pointer}button[aria-pressed="true"]{background:#127a89;border-color:#2ed4df}table{width:100%;border-collapse:collapse;font-size:.9rem}th{text-align:left;color:#90acc7}td,th{padding:9px 8px;border-bottom:1px solid #294058}td.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}a{color:#5ad7e5}a:hover{text-decoration:none}.track{height:11px;max-width:100%;background:#22344b;border-radius:7px;overflow:hidden}.bar{height:100%;background:linear-gradient(90deg,#19788d,#55d2db);border-radius:7px}.section-note{font-size:.84rem}.value{font-size:1.05rem;font-weight:bold;color:#f1f6ff}.pill{font-size:.73rem;border:1px solid var(--edge);padding:2px 7px;border-radius:100px;white-space:nowrap;color:var(--warn)}@media(max-width:700px){.grid{display:block}.numbers{grid-template-columns:1fr 1fr}main{padding:18px 12px}}@media(max-width:400px){.numbers{grid-template-columns:1fr}}
</style></head><body><main>
<header><div class="tag">FiscalRazor / v1.0 / Evidence first</div><h1>What could the reform actually accomplish?</h1><p>Legally specified 12-provision proposal · official standalone policy analogues · exact mathematical constraints · intermediate/low/high Medicare stress tests.</p><div class="warn">This is not a joint federal score. The 2024 CBO/JCT options below are <b>different policies under a different baseline</b>. Their dollar amounts cannot be added, assigned to our draft, or extrapolated to 2036.</div></header>
<div class="grid">
<section class="card wide"><h2>1 · Fiscal objective against the frozen CBO February 2026 baseline</h2><div class="choice" id="yearButtons"></div><div class="numbers" id="yearNumbers"></div><p class="section-note">The 5% all-PCE figure is gross under unrealistically full taxability, no behavior and no rebates. The legal VAT includes exemptions and refundable credits. This is a conditional fixed-base envelope, not a score or general tax-base upper bound.</p></section>
<section class="card wide"><h2>2 · 12 policies compared with independent CBO option estimates</h2><p>December 2024 JCT/CBO FY2034 single-option estimates in $ billions. The bars show the individual analogues relative to the <i>different</i> February 2026 baseline's FY2034 gap solely to compare scale.</p><div style="overflow:auto"><table><thead><tr><th>§</th><th>Draft provision</th><th>FY2034 official analogue</th><th>Relative scale</th><th>Source</th></tr></thead><tbody id="optionsRows"></tbody></table></div></section>
<section class="card"><h2>3 · Medicare HI by scenario</h2><div class="choice" id="hiButtons"></div><div class="numbers" style="grid-template-columns:repeat(2,minmax(0,1fr))" id="hiNumbers"></div><p id="hiNarrative"></p><p class="section-note">Trustees' Table III.B5. Additional §§112 taxes added to fixed baseline. Future interest, induced wages, provider behavior and 75-year adequacy are not modeled.</p></section>
<section class="card"><h2>4 · VAT credit break-even</h2><p>Symbolic household income Y and taxable consumption C expressed in multiples of the household's official poverty guideline P.</p><table><thead><tr><th>Y/P</th><th>Net-zero VAT spending C/P</th><th>Net VAT when C=1.25P</th></tr></thead><tbody id="vatRows"></tbody></table><p class="section-note">A household can receive the full credit yet pay a net VAT. Not a weighted household result; actual households require CPS/CE/IRS joint imputation.</p></section>
<section class="card wide"><h2>5 · Quantified edges of our exact drafted law</h2><div class="numbers" id="exactLawNumbers"></div><p>2028 surtax is a mathematical lower bound on mechanical liability among top-1% projected returns, conditional on the published CBO aggregate distribution and assuming no taxpayer behavior. Defense value is <b>budget authority only</b>, not FY cash savings or a combined score.</p></section></div><footer><p>Source families: <a href="https://github.com/US-CBO/cbo-data">CBO February 2026</a>, <a href="https://www.cbo.gov/budget-options/60961">CBO December 2024 options</a>, <a href="https://www.cms.gov/oact/tr/2026">CMS 2026 trustees</a>, <a href="https://www.ssa.gov/oact/solvency/provisions/tables/table_run214.html">SSA 2026 option E2.5</a>. All calculations are reproducible in <code>scripts/run_potential_v10.py</code>.</p></footer>
</main><script>const DATA=__DATA__;
const n=(x,d=1)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const el=id=>document.getElementById(id);const safely=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
let year=2034,scenario='intermediate';
function metric(title,value){return `<div class="metric"><small>${safely(title)}</small><strong>${safely(value)}</strong></div>`}
function showYear(){el('yearButtons').innerHTML=[2027,2028,2030,2032,2034,2036].map(y=>`<button aria-pressed="${year===y}" onclick="year=${y};showYear()">FY${y}</button>`).join('');const t=DATA.target.find(r=>Number(r.fy)===year),v=DATA.vat.find(r=>Number(r.fy)===year);el('yearNumbers').innerHTML=metric('Baseline deficit',`$${n(t.baseline_deficit_bn)}B`)+metric('Gap to 3%-of-GDP deficit',`$${n(t.static_gap_to_3pct_bn)}B`)+metric('5% of all PCE, gross before rebates',`$${n(v.fixed_all_pce_gross_bn)}B`);}
function showOptions(){const titles={'101':'VAT with credits','102':'High-income surtax','103':'Itemized deduction limit','104':'Employer health exclusion cap','105':'Corporate income tax rate','106':'Additional high-earnings OASDI','107':'OASDI phased rate rise','108':'Progressive price-indexing','109':'Medicare Advantage rules','110':'Site-neutral clinic payments','111':'Defense BA ceiling','112':'HI payroll contribution'};el('optionsRows').innerHTML=DATA.options.map(r=>{const has=r.official_analogue_bn!=='';const value=has?Number(r.official_analogue_bn):0;const pct=has?Number(r.comparator_as_pct_of_2026_baseline_target):0;return `<tr><td>${r.section}</td><td>${safely(titles[r.section])}<div class="section-note">${safely(r.comparator||'No matching budget option')}</div></td><td class="num">${has?'$'+n(value)+'B':'not scored'}</td><td>${has?`<div class="track"><div class="bar" style="width:${Math.min(100,pct)}%"></div></div><small>${n(pct)}% scale</small>`:'<span class="pill">unavailable</span>'}</td><td><a href="${safely(r.source)}" target="_blank" rel="noopener">Official source</a></td></tr>`}).join('')}
function showHI(){el('hiButtons').innerHTML=[['low_cost','Low cost'],['intermediate','Intermediate'],['high_cost','High cost']].map(([s,l])=>`<button aria-pressed="${scenario===s}" onclick="scenario='${s}';showHI()">${l}</button>`).join('');const r=DATA.thresholds.find(x=>x.scenario===scenario),last=DATA.hi.find(x=>x.scenario===scenario&&x.calendar_year==='2035');el('hiNumbers').innerHTML=metric('2035 reserves after phased tax',`$${n(r.year_end_assets_2035_with_draft_bn)}B`)+metric('2035 reserve / annual expenditure',`${n(r.year_end_2035_reserve_ratio_pct)}%`)+metric('2035 100%-reserve full-phase rate',`${n(r.funding_rate_full_phase_pp_if_scaled_to_2035_100pct,3)} pp`)+metric('Draft full-phase addition','0.750 pp');el('hiNarrative').textContent=(scenario==='high_cost'?'High-cost still exhausts reserves by end-2033. ':'')+'The 100% threshold applies to the 2035 end-year only, not every year or the 75-year horizon.'}
function showVAT(){el('vatRows').innerHTML=DATA.household.map(r=>`<tr><td>${n(r.annual_MAGI_over_HHS_guideline,2)}</td><td>${n(r.taxable_consumption_over_guideline_at_net_VAT_zero,2)}</td><td class="num">${n(100*Number(r.tax_on_C_equal_1_25P_less_rebate_over_P),3)}% of P</td></tr>`).join('')}
function showExact(){let a=DATA.surtax[0],b=DATA.defense.find(x=>x.fy==='2034');el('exactLawNumbers').innerHTML=metric('CY2028 §102 top-1% liability lower bound',`$${n(a.nonbehavioral_top1_MAGI_surtax_liability_lower_bound_bn,2)}B`)+metric('FY2034 §111 defense BA difference',`$${n(b.mechanical_base_BA_delta_bn,2)}B`)+metric('§102 top-1% 2028 CBO AGI',`$${n(a.top1_AGI_total_bn,1)}B`)}
showYear();showOptions();showHI();showVAT();showExact();</script></body></html>'''.replace('__DATA__',serialized)
p=ROOT/'policy_potential_v10.html';p.write_text(htmlsource,encoding='utf-8');print('WROTE DASHBOARD',p,len(htmlsource), 'chars')
